"""Camera-only UI; every saved sample contains a full still and its metadata."""
HTML = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Palmprint · High-resolution capture</title><style>
:root{--ink:#172d31;--muted:#687b7d;--line:#dce5e3;--green:#17654b;--paper:#f4f7f5}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px system-ui,-apple-system,sans-serif}header,main{max-width:1240px;margin:auto;padding:24px}header{display:flex;justify-content:space-between;align-items:center;gap:16px}h1{margin:4px 0;font-size:27px;letter-spacing:-.5px}.eyebrow{font-size:12px;letter-spacing:2px;color:var(--green);font-weight:700}.sub{color:var(--muted);font-size:14px;line-height:1.6;margin:5px 0}.badge{font-size:13px;background:#e3ede7;padding:9px 13px;border-radius:30px;white-space:nowrap}.badge.error{background:#fbe7e2;color:#9e352a}main{padding-top:0}.top{display:grid;grid-template-columns:minmax(0,1.9fr) minmax(290px,1fr);gap:20px}.card{background:#fff;border:1px solid var(--line);border-radius:18px;padding:22px}h2{font-size:17px;margin:0 0 14px}.cardhead{display:flex;align-items:center;justify-content:space-between;gap:12px}.live{position:relative;border-radius:12px;overflow:hidden;aspect-ratio:4/3;background:#15201f}.live img{width:100%;height:100%;object-fit:contain;display:block}.guide{position:absolute;inset:8%;border:1px dashed #ffffff66;border-radius:20px;pointer-events:none}.live-caption{position:absolute;left:14px;bottom:14px;background:#122a25b8;color:#fff;padding:7px 10px;border-radius:8px;font-size:12px;pointer-events:none}.help{color:var(--muted);font-size:13px;line-height:1.65}.counter{font:700 20px system-ui}.progress{height:5px;background:#e6ece8;border-radius:8px;overflow:hidden;margin:14px 0}.progress span{display:block;width:0;height:100%;background:var(--green);transition:width .25s}.action{width:100%;border:0;border-radius:12px;background:var(--green);color:#fff;font:650 18px system-ui;padding:17px;cursor:pointer}.action:disabled{opacity:.5;cursor:wait}.keyboard{font-size:12px;font-weight:400;opacity:.75;margin-left:12px}kbd{font:inherit;border:1px solid currentColor;border-radius:4px;padding:2px 5px}label{display:block;font-size:14px;font-weight:600;margin:15px 0 7px}input,select,textarea{font:inherit;width:100%;padding:11px 12px;border:1px solid #ccd7d2;border-radius:9px;background:#fff;color:var(--ink)}input:focus,select:focus,textarea:focus{outline:2px solid #aed5c3;outline-offset:1px}textarea{resize:vertical;min-height:65px}.hands{display:flex;gap:10px}.hands label{margin:0;flex:1}.hands input{position:absolute;opacity:0;width:1px;height:1px}.hands span{display:block;text-align:center;padding:12px;border:1px solid var(--line);border-radius:9px;cursor:pointer}.hands input:checked+span{border-color:var(--green);background:#e9f3ec;color:var(--green)}.hands input:disabled+span{cursor:default;opacity:.75}details{margin-top:20px;border-top:1px solid var(--line);padding-top:16px}summary{cursor:pointer;color:var(--muted);font-size:14px}.row{display:grid;grid-template-columns:1fr 1fr;gap:12px}.secondary{font:inherit;border:1px solid var(--line);background:#fff;border-radius:9px;padding:10px 13px;cursor:pointer;color:var(--ink)}.secondary:disabled{opacity:.5}.actions{display:flex;flex-wrap:wrap;gap:9px;margin-top:14px}.download{display:inline-block;color:var(--green);text-decoration:none;font-weight:650;font-size:14px;padding:10px 12px;background:#e9f3ec;border-radius:9px}.status{margin-top:14px;min-height:45px;padding:12px;border-radius:9px;background:#f1f5f2;font-size:14px;line-height:1.6;overflow-wrap:anywhere}.status.error{background:#fff0e9;color:#9a3a25}.section{margin-top:20px}.thumbs{display:grid;grid-template-columns:repeat(10,minmax(0,1fr));gap:8px}.thumb{padding:0;background:#edf1ed;border:2px solid transparent;border-radius:8px;cursor:pointer;overflow:hidden;color:var(--ink)}.thumb img{width:100%;aspect-ratio:4/3;object-fit:cover;display:block}.thumb span{display:block;font:600 12px system-ui;padding:5px}.thumb.selected{border-color:var(--green)}.inspect{display:grid;grid-template-columns:minmax(0,2fr) minmax(220px,1fr);gap:18px;margin-top:18px}.full{width:100%;max-height:520px;object-fit:contain;background:#eef2ed;border-radius:10px;cursor:crosshair}canvas{display:block;width:100%;aspect-ratio:1;background:#eff3ee;border-radius:10px;image-rendering:pixelated}.links{display:flex;gap:14px;flex-wrap:wrap;margin:10px 0}.links a{color:var(--green);font-size:13px}.saved{display:flex;justify-content:space-between;align-items:center;gap:15px;padding:14px 0;border-top:1px solid var(--line)}.saved strong{font-size:14px}.saved small{display:block;font-size:12px;color:var(--muted);line-height:1.7}.empty{color:var(--muted);font-size:14px;padding:10px 0}[hidden]{display:none!important}@media(max-width:850px){header,main{padding:16px}.top{grid-template-columns:1fr}.thumbs{grid-template-columns:repeat(5,minmax(0,1fr))}.inspect{grid-template-columns:1fr}.card{padding:18px}.zoom{max-width:360px}.keyboard{display:none}}@media(max-width:460px){header{align-items:flex-start}h1{font-size:23px}.badge{font-size:11px;padding:8px}.saved{align-items:flex-start}.saved small{max-width:190px}}
.danger{color:#a63c30;border-color:#e8c9c2}.danger:hover:not(:disabled){background:#fff0eb}
</style></head><body>
<header><div><div class="eyebrow">PALM CAPTURE</div><h1>High-resolution palmprint capture</h1><p class="sub">Save the full original first, then extract ROI and evaluate offline. · <a href="/palmir">PalmIR Restoration comparison</a></p></div><span id="camera" class="badge">Connecting to camera…</span></header>
<main><div class="top"><section class="card"><div class="cardhead"><h2>Live view</h2><span id="counter" class="counter">0 / 10</span></div><div class="live"><img id="live" src="/frame.jpg" alt="Live camera feed"><div class="guide"></div><div class="live-caption">Keep the palm edges, finger bases and finger gaps in view · Avoid placing your hand too close to the lens</div></div><p class="help">The dashed outline is a framing guide. Spread your fingers naturally and check that the finger gaps and palm ridges are clear. Keep distance and lighting consistent.</p><div class="progress"><span id="bar"></span></div><button id="capture" class="action" disabled>Connect the camera to capture</button><div class="actions"><button id="finish" class="secondary" hidden>Finish session</button><button id="switch" class="secondary">Switch hands</button><a id="download" class="download" hidden>Download session ZIP</a></div><div id="status" class="status" role="status" aria-live="polite">Enter a subject ID and choose a hand to start capturing.</div></section>
<section class="card"><h2>Session labels</h2><p class="sub">Use the same hand throughout each session. Maximum: 10 photos.</p><label for="subject">Subject ID</label><input id="subject" maxlength="40" placeholder="e.g. p01" autocomplete="off" pattern="[A-Za-z0-9_-]+"><label>Hand</label><div class="hands"><label><input type="radio" name="hand" value="left"><span>Left hand</span></label><label><input type="radio" name="hand" value="right"><span>Right hand</span></label></div><details><summary>Capture conditions (optional)</summary><div class="row"><div><label for="background">Background</label><select id="background"><option value="existing">Current background</option><option value="white">White paper</option><option value="other">Other</option></select></div><div><label for="distance">Distance / cm</label><input id="distance" type="number" min="5" max="100" step="0.5" placeholder="e.g. 30"></div></div><label for="notes">Lighting and notes</label><textarea id="notes" maxlength="200" placeholder="e.g. Steady IR light, fixed mount"></textarea></details><p class="help">Saves full-resolution photos, hand labels, timestamps, exposure and gain. No automatic cropping or recognition during capture.</p></section></div>
<section class="card section"><div class="cardhead"><h2>Session photos</h2><button id="delete-photo" class="secondary danger" disabled>Delete selected photo</button></div><p class="help">Select a thumbnail. You can retake a deleted photo; its original moves to the recovery folder on the Pi.</p><div id="thumbs" class="thumbs"></div><p id="empty" class="empty">No photos in this session yet.</p><div id="inspect" class="inspect" hidden><div><img id="full" class="full" alt="Full-resolution original"><div class="links"><a id="full-link" target="_blank">Open original</a><a id="metadata-link" target="_blank">Capture settings</a></div><p id="photo-info" class="help"></p></div><div class="zoom"><canvas id="zoom" width="512" height="512"></canvas><p class="help">Click a photo on the left to inspect its original pixels. Zooming does not generate or save an ROI.</p></div></div></section>
<section class="card section"><h2>Saved sessions</h2><div id="sessions" class="empty">Loading…</div></section></main>
<script>
const $=id=>document.getElementById(id),camera=$('camera'),capture=$('capture'),status=$('status'),full=$('full');
let batch={phase:'idle',sample_ids:[],captured:0},ready=false,busy=false,signature='',selected=null,seenSession=null,previewUrl=null;
const formInputs=[$('subject'),$('background'),$('distance'),$('notes'),...document.querySelectorAll('input[name=hand]')];
const handValue=()=>document.querySelector('input[name=hand]:checked')?.value||'';
function say(text,error=false){status.textContent=text;status.className='status'+(error?' error':'')}
function labels(){const subject=$('subject').value.trim(),hand=handValue();if(!/^[A-Za-z0-9_-]{1,40}$/.test(subject))throw Error('Enter a subject ID using only letters, digits, _ or -.');if(!hand)throw Error('Choose left or right hand.');return{subject,hand,background:$('background').value,distance_cm:$('distance').value,notes:$('notes').value,client_time:new Date().toISOString()}}
async function api(path,data){const r=await fetch(path,{method:data===undefined?'GET':'POST',headers:data===undefined?{}:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data),cache:'no-store'});const d=await r.json();if(!r.ok)throw Error(d.message||'Request failed');return d}
function controls(){const active=batch.phase==='await_hand';for(const el of formInputs)el.disabled=busy||active;capture.disabled=busy||!ready;capture.textContent=busy?'Processing…':active?`Capture photo ${batch.captured+1} · Full-resolution original`:batch.phase==='complete'?'Start new session · Capture photo 1':'Capture photo 1 · Start session';if(!busy){const hint=document.createElement('span');hint.className='keyboard';hint.innerHTML='<kbd>Space</kbd> Capture';capture.append(hint)}$('counter').textContent=`${batch.captured||0} / 10`;$('bar').style.width=(batch.captured||0)*10+'%';$('finish').hidden=!active;$('finish').disabled=busy;$('switch').disabled=busy;$('download').hidden=!batch.session_id||!batch.captured;if(batch.session_id)$('download').href='/api/collection/session/'+encodeURIComponent(batch.session_id)+'.zip';deleteControls()}
function deleteControls(){const index=(batch.sample_ids||[]).indexOf(selected);$('delete-photo').disabled=busy||index<0;$('delete-photo').textContent=index<0?'Delete selected photo':`Delete photo ${index+1}`;for(const b of document.querySelectorAll('[data-delete-session]'))b.disabled=busy}
async function showPhoto(id){selected=id;deleteControls();for(const b of $('thumbs').children)b.classList.toggle('selected',b.dataset.id===id);try{const m=await api('/api/collection/sample/'+encodeURIComponent(id)+'/metadata.json');if(selected!==id)return;const base='/api/collection/sample/'+encodeURIComponent(id);full.src=base+'/full.jpg';$('full-link').href=base+'/full.jpg';$('metadata-link').href=base+'/metadata.json';$('inspect').hidden=false;$('photo-info').textContent=`${m.subject} · ${m.hand==='left'?'Left hand':'Right hand'} · ${m.width}×${m.height}`+(m.exposure_ms==null?'':` · Exposure ${Number(m.exposure_ms).toFixed(1)} ms`)+(m.analogue_gain==null?'':` · Gain ${Number(m.analogue_gain).toFixed(2)}`)}catch(e){if(selected===id)say(e.message,true)}}
function thumbnails(){const ids=batch.sample_ids||[],key=ids.join(',');if(key===signature)return;signature=key;$('thumbs').replaceChildren();$('empty').hidden=ids.length>0;for(const [i,id]of ids.entries()){const b=document.createElement('button');b.className='thumb';b.dataset.id=id;b.title='View photo '+(i+1);const img=document.createElement('img');img.src='/api/collection/sample/'+encodeURIComponent(id)+'/thumbnail.jpg';img.alt='Photo '+(i+1)+' (full resolution)';const label=document.createElement('span');label.textContent=String(i+1).padStart(2,'0');b.append(img,label);b.onclick=()=>showPhoto(id);$('thumbs').append(b)}if(ids.length)showPhoto(ids.at(-1));else{selected=null;$('inspect').hidden=true;full.removeAttribute('src');$('zoom').getContext('2d').clearRect(0,0,512,512)}deleteControls()}
async function refresh(){const d=await api('/api/status');ready=Boolean(d.camera_ready)&&!d.error;camera.textContent=d.error?'Camera error':ready?`${(d.capture_size||[3280,2464]).join(' × ')} · Connected`:'Connecting to camera…';camera.className='badge'+(d.error?' error':'');batch=d.highres_batch||{phase:'idle',captured:0,sample_ids:[]};if(batch.session_id&&seenSession!==batch.session_id){seenSession=batch.session_id;$('subject').value=batch.subject||'';for(const h of document.querySelectorAll('input[name=hand]'))h.checked=h.value===batch.hand;$('background').value=batch.background||'existing';$('distance').value=batch.distance_cm??'';$('notes').value=batch.notes||''}thumbnails();controls()}
async function poll(){if(!busy)try{await refresh()}catch(e){ready=false;camera.textContent='Disconnected';camera.className='badge error';controls()}setTimeout(poll,800)}
async function preview(){try{const r=await fetch('/frame.jpg?t='+Date.now(),{cache:'no-store'});if(r.ok){const next=URL.createObjectURL(await r.blob()),old=previewUrl;previewUrl=next;$('live').src=next;if(old)URL.revokeObjectURL(old)}}catch(e){}setTimeout(preview,250)}
capture.onclick=async()=>{if(busy||!ready)return;busy=true;controls();try{if(batch.phase!=='await_hand'){const l=labels();batch=await api('/api/collection/start-batch',l);try{localStorage.setItem('palm_capture_labels',JSON.stringify(l))}catch(e){}}say('Saving the full-resolution original. Keep your hand still…');const d=await api('/api/collection/capture-batch',{client_time:new Date().toISOString()});say(d.phase==='complete'?'10 saved. Download the session or switch hands to start another.':`Photo ${d.sample_index} saved. Continue capturing or remove and reposition your hand.`);await refreshSessions()}catch(e){say('Capture incomplete: '+e.message,true)}finally{busy=false;await refresh().catch(()=>{});controls()}};
async function finish(){if(batch.phase==='await_hand')await api('/api/collection/abandon-batch',{});seenSession=null;signature='__reset__';await refresh();await refreshSessions()}
$('finish').onclick=async()=>{if(busy)return;busy=true;controls();try{const count=batch.captured;await finish();say(`Session finished. ${count} originals retained. Download them below.`)}catch(e){say(e.message,true)}finally{busy=false;controls()}};
$('switch').onclick=async()=>{if(busy)return;const next=handValue()==='left'?'right':'left';busy=true;controls();try{await finish();for(const h of document.querySelectorAll('input[name=hand]'))h.checked=h.value===next;say(`Switched to ${next==='left'?'Left hand':'Right hand'}. Your next capture starts a new session.`)}catch(e){say(e.message,true)}finally{busy=false;controls()}};
document.addEventListener('keydown',e=>{if(e.code!=='Space'||e.repeat||['INPUT','TEXTAREA','SELECT','BUTTON'].includes(e.target.tagName))return;e.preventDefault();if(!capture.disabled)capture.click()});
function zoomAt(x,y){if(!full.naturalWidth)return;const size=Math.min(512,full.naturalWidth,full.naturalHeight),sx=Math.max(0,Math.min(full.naturalWidth-size,x-size/2)),sy=Math.max(0,Math.min(full.naturalHeight-size,y-size/2));const ctx=$('zoom').getContext('2d');ctx.imageSmoothingEnabled=false;ctx.clearRect(0,0,512,512);ctx.drawImage(full,sx,sy,size,size,0,0,512,512)}
full.onload=()=>zoomAt(full.naturalWidth/2,full.naturalHeight/2);full.onclick=e=>{const box=full.getBoundingClientRect(),scale=Math.min(box.width/full.naturalWidth,box.height/full.naturalHeight),w=full.naturalWidth*scale,h=full.naturalHeight*scale,x=e.clientX-box.left-(box.width-w)/2,y=e.clientY-box.top-(box.height-h)/2;if(x>=0&&y>=0&&x<=w&&y<=h)zoomAt(x/scale,y/scale)};
async function deleteSelected(){if(busy||!selected)return;const id=selected,session=batch.session_id,ids=batch.sample_ids,index=ids.indexOf(id),next=ids[index+1]||ids[index-1];if(index<0||!confirm(`Delete session photo ${index+1}?\nYou can retake it. The original will move to the Pi recovery folder.`))return;busy=true;controls();deleteControls();selected=null;try{await api('/api/collection/delete-sample',{session_id:session,sample_id:id});await refresh();if(next&&(batch.sample_ids||[]).includes(next))await showPhoto(next);await refreshSessions();say(`Deleted photo ${index+1}. Remaining: ${batch.captured} photos. You can take more.`)}catch(e){say('Deletion incomplete: '+e.message,true)}finally{busy=false;await refresh().catch(()=>{});controls();deleteControls()}}
async function deleteSession(s){if(busy||!confirm(`Delete ${s.subject} · ${s.hand==='left'?'Left hand':'Right hand'} session, including all ${s.sample_count} photos?\nThe originals and session information will move to the Pi recovery folder.`))return;busy=true;controls();deleteControls();try{await api('/api/collection/delete-session',{session_id:s.session_id});await refresh();await refreshSessions();say(`Deleted photos from this session: ${s.sample_count}. Originals moved to the recovery folder.`)}catch(e){say('Deletion incomplete: '+e.message,true)}finally{busy=false;await refresh().catch(()=>{});controls();deleteControls()}}
$('delete-photo').onclick=deleteSelected;
async function refreshSessions(){try{const d=await api('/api/collection/sessions');$('sessions').replaceChildren();const sessions=(d.sessions||[]).filter(s=>s.sample_count>0);if(!sessions.length){$('sessions').textContent='No saved sessions yet.';return}for(const s of sessions){const row=document.createElement('div');row.className='saved';const info=document.createElement('div'),title=document.createElement('strong'),meta=document.createElement('small');title.textContent=`${s.subject} · ${s.hand==='left'?'Left hand':'Right hand'} · ${s.sample_count} photos`;meta.textContent=s.session_id;info.append(title,meta);const actions=document.createElement('div');actions.className='actions';const link=document.createElement('a');link.className='download';link.href='/api/collection/session/'+encodeURIComponent(s.session_id)+'.zip';link.textContent='Download ZIP';const remove=document.createElement('button');remove.className='secondary danger';remove.dataset.deleteSession=s.session_id;remove.textContent='Delete session';remove.disabled=busy;remove.onclick=()=>deleteSession(s);actions.append(link,remove);row.append(info,actions);$('sessions').append(row)}}catch(e){$('sessions').textContent='Cannot load saved sessions right now.'}}
try{const l=JSON.parse(localStorage.getItem('palm_capture_labels')||'null');if(l){$('subject').value=l.subject||'';$('background').value=l.background||'existing';$('distance').value=l.distance_cm||'';$('notes').value=l.notes||'';for(const h of document.querySelectorAll('input[name=hand]'))h.checked=h.value===l.hand}}catch(e){}
preview();poll();refreshSessions();setInterval(()=>{if(!busy)refreshSessions()},10000);
</script></body></html>'''
